func computeFib(_ n: Int) -> Int {
    var memo: [Int: Int] = [:]
    func helper(_ k: Int) -> Int {
        if k <= 1 { return k }
        if let cached = memo[k] { return cached }
        let res = helper(k - 1) + helper(k - 2)
        memo[k] = res
        return res
    }
    return helper(n)
}
