func uniquePaths(_ m: Int, _ n: Int) -> Int {
    var row = Array(repeating: 1, count: n)
    for _ in 1..<m {
        var newRow = Array(repeating: 1, count: n)
        for c in 1..<n {
            newRow[c] = newRow[c - 1] + row[c]
        }
        row = newRow
    }
    return row[n - 1]
}
print("\(uniquePaths(3, 7)) \(uniquePaths(3, 2))")

