// Test with [1, 5, 11, 5] and [1, 2, 3, 5]
// Print both results separated by a space

questions.modelAnswer:
func canPartition(_ nums: [Int]) -> Bool {
    let sum = nums.reduce(0, +)
    guard sum % 2 == 0 else { return false }
    let target = sum / 2
    var dp = Set<Int>([0])
    for n in nums {
        var nextDP = dp
        for t in dp {
            let nextVal = t + n
            if nextVal == target { return true }
            if nextVal < target { nextDP.insert(nextVal) }
        }
        dp = nextDP
    }
    return dp.contains(target)
}
let n1 = [1, 5, 11, 5]
let n2 = [1, 2, 3, 5]
print("\(canPartition(n1)) \(canPartition(n2))")
